function StarRating({ score }) {
  if (!score) return null;
  const full = Math.floor(score);
  return (
    <span style={{ color: "#f59e0b", fontSize: 11, letterSpacing: 1 }}>
      {"★".repeat(full)}{"☆".repeat(5 - full)}
    </span>
  );
}

